+    /// Writes `body` over `file` and gives it back the modification time it had, so its stamp is unchanged.
+    fn rewrite_keeping_stamp(file: &Utf8Path, body: &[u8]) {
+        let modified = std::fs::metadata(file).unwrap().modified().unwrap();
